int best = 0;

int height(TreeNode* node) {        // returns height in edges
    if (!node) return 0;
    int l = height(node->left);
    int r = height(node->right);
    best = max(best, l + r);        // longest path through this node
    return 1 + max(l, r);
}
int diameter(TreeNode* root) { best = 0; height(root); return best; }

