class Solution:
    def diameterOfBinaryTree(self, root) -> int:
        self.best = 0
        def height(r):
            if not r:
                return 0
            L, R = height(r.left), height(r.right)
            self.best = max(self.best, L + R)
            return 1 + max(L, R)
        height(root)
        return self.best

