class Solution:
    def maxPathSum(self, root) -> int:
        self.best = float('-inf')
        def gain(r):
            if not r:
                return 0
            L = max(0, gain(r.left))
            R = max(0, gain(r.right))
            self.best = max(self.best, r.val + L + R)
            return r.val + max(L, R)
        gain(root)
        return self.best

class Solution {
    int best = 0;
    int arm(TreeNode* r) {
        if (!r) return 0;
        int L = arm(r->left), R = arm(r->right);
        int la = (r->left && r->left->val == r->val) ? L + 1 : 0;
        int ra = (r->right && r->right->val == r->val) ? R + 1 : 0;
        best = max(best, la + ra);
        return max(la, ra);
    }
public:
    int longestUnivaluePath(TreeNode* root) { arm(root); return best; }
};

class Solution:
    def longestUnivaluePath(self, root) -> int:
        self.best = 0
        def arm(r):
            if not r:
                return 0
            L, R = arm(r.left), arm(r.right)
            la = L + 1 if r.left and r.left.val == r.val else 0
            ra = R + 1 if r.right and r.right.val == r.val else 0
            self.best = max(self.best, la + ra)
            return max(la, ra)
        arm(root)
        return self.best

class Solution {
    pair<int,int> bfs(int src, vector<vector<int>>& adj) {
        int n = adj.size(); vector<int> dist(n, -1); queue<int> q;
        dist[src] = 0; q.push(src); int far = src;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (dist[u] > dist[far]) far = u;
            for (int v : adj[u]) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }
        }
        return {far, dist[far]};
    }
public:
    int treeDiameter(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        auto [u, _] = bfs(0, adj);
        auto [v, d] = bfs(u, adj);
        return d;
    }
};

from collections import deque
class Solution:
    def treeDiameter(self, edges: list[list[int]]) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b); adj[b].append(a)
        def bfs(src):
            dist = [-1] * n
            dist[src] = 0
            q = deque([src]); far = src
            while q:
                u = q.popleft()
                if dist[u] > dist[far]:
                    far = u
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1; q.append(v)
            return far, dist[far]
        u, _ = bfs(0)
        v, d = bfs(u)
        return d

class Solution {
public:
    vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges) {
        if (n == 1) return {0};
        vector<vector<int>> adj(n); vector<int> deg(n, 0);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); deg[e[0]]++; deg[e[1]]++; }
        queue<int> q;
        for (int i = 0; i < n; i++) if (deg[i] == 1) q.push(i);
        int remaining = n;
        while (remaining > 2) {
            int sz = q.size(); remaining -= sz;
            while (sz--) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) if (--deg[v] == 1) q.push(v);
            }
        }
        vector<int> res;
        while (!q.empty()) { res.push_back(q.front()); q.pop(); }
        return res;
    }
};

from collections import deque
class Solution:
    def findMinHeightTrees(self, n: int, edges: list[list[int]]) -> list[int]:
        if n == 1:
            return [0]
        adj = [[] for _ in range(n)]
        deg = [0] * n
        for a, b in edges:
            adj[a].append(b); adj[b].append(a); deg[a] += 1; deg[b] += 1
        q = deque(i for i in range(n) if deg[i] == 1)
        remaining = n
        while remaining > 2:
            for _ in range(len(q)):
                u = q.popleft()
                remaining -= 1
                for v in adj[u]:
                    deg[v] -= 1
                    if deg[v] == 1:
                        q.append(v)
        return list(q)
